# Let's try: path 0-1-2-...-19 plus edges (0,6), (6,12), (12,18)
# This gives 19 + 3 = 22 edges

edges = [(i, i+1) for i in range(19)] + [(0,6), (6,12), (12,18)]

n = 20
adj = [[] for _ in range(n)]
for u,v in edges:
    adj[u].append(v)
    adj[v].append(u)

print("Num edges:", len(edges))

# Check girth
def girth(adj, n):
    import sys
    best = sys.maxsize
    for s in range(n):
        dist = [-1]*n
        parent = [-1]*n
        dist[s] = 0
        q = [s]
        idx = 0
        while idx < len(q):
            u = q[idx]
            idx += 1
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif parent[u] != v and parent[v] != u:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < best:
                        best = cycle_len
    return best if best != sys.maxsize else -1

print("Girth:", girth(adj, n))

# Check 3-colorability
def is_3_colorable(adj, n):
    colors = [-1]*n
    order = sorted(range(n), key=lambda x: len(adj[x]), reverse=True)

    def dfs(i):
        if i == n:
            return True
        v = order[i]
        used = set()
        for nb in adj[v]:
            if colors[nb] != -1:
                used.add(colors[nb])
        for c in range(3):
            if c not in used:
                colors[v] = c
                if dfs(i+1):
                    return True
                colors[v] = -1
        return False

    return dfs(0)

print("3-colorable:", is_3_colorable(adj, n))

# Let's also verify by finding a coloring
def find_3_coloring(adj, n):
    colors = [-1]*n
    order = sorted(range(n), key=lambda x: len(adj[x]), reverse=True)

    def dfs(i):
        if i == n:
            return True
        v = order[i]
        used = set()
        for nb in adj[v]:
            if colors[nb] != -1:
                used.add(colors[nb])
        for c in range(3):
            if c not in used:
                colors[v] = c
                if dfs(i+1):
                    return True
                colors[v] = -1
        return False

    if dfs(0):
        return colors
    return None

colors = find_3_coloring(adj, n)
print("Coloring:", colors)
